"""Minimal, privacy-conscious client for OpenAI's Responses API.

Only Python's standard library is required.  Prompts and API keys are never
logged or included in exceptions, and response storage is disabled by default.
"""

from __future__ import annotations

import json
import os
import socket
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Mapping


_RESPONSES_URL = "https://api.openai.com/v1/responses"


class OpenAIError(RuntimeError):
    """An API, network, or response-format error with sensitive data omitted."""


@dataclass(frozen=True)
class Response:
    """The useful parts of a Responses API result."""

    text: str
    id: str | None
    model: str | None
    raw: Mapping[str, Any]


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    """Do not risk forwarding an Authorization header to another origin."""

    def redirect_request(self, req: Any, fp: Any, code: int, msg: str,
                         headers: Any, newurl: str) -> None:
        return None


class OpenAIClient:
    """Send text prompts to the OpenAI Responses API.

    Args:
        api_key: OpenAI API key. If omitted, ``OPENAI_API_KEY`` is read.
        model: Model ID to use for requests.
        timeout: Total socket timeout in seconds.
    """

    def __init__(
        self,
        *,
        api_key: str | None = None,
        model: str = "gpt-5-mini",
        timeout: float = 60.0,
    ) -> None:
        key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
        if not key or not key.strip():
            raise ValueError("Set OPENAI_API_KEY or pass api_key explicitly")
        if not model or not model.strip():
            raise ValueError("model must be a non-empty string")
        if timeout <= 0:
            raise ValueError("timeout must be greater than zero")

        self._api_key = key.strip()
        self.model = model.strip()
        self.timeout = float(timeout)
        self._opener = urllib.request.build_opener(_NoRedirect())

    def respond(
        self,
        prompt: str,
        *,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
    ) -> Response:
        """Send *prompt* and return its text plus the decoded response.

        This method deliberately does not print or log request/response data.
        OpenAI response storage is disabled with ``store: false``.
        """
        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")
        if instructions is not None and not isinstance(instructions, str):
            raise TypeError("instructions must be a string or None")
        if max_output_tokens is not None and max_output_tokens <= 0:
            raise ValueError("max_output_tokens must be greater than zero")

        payload: dict[str, Any] = {
            "model": self.model,
            "input": prompt,
            "store": False,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens

        request = urllib.request.Request(
            _RESPONSES_URL,
            data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {self._api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
                "User-Agent": "openai-client-stdlib/1.0",
            },
            method="POST",
        )

        try:
            with self._opener.open(request, timeout=self.timeout) as reply:
                body = reply.read()
                request_id = reply.headers.get("x-request-id")
        except urllib.error.HTTPError as exc:
            request_id = exc.headers.get("x-request-id") if exc.headers else None
            suffix = f" (request ID: {request_id})" if request_id else ""
            raise OpenAIError(f"OpenAI API returned HTTP {exc.code}{suffix}") from None
        except (urllib.error.URLError, TimeoutError, socket.timeout):
            raise OpenAIError("Could not reach the OpenAI API") from None

        try:
            decoded = json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIError("OpenAI API returned an invalid JSON response") from None
        if not isinstance(decoded, dict):
            raise OpenAIError("OpenAI API returned an unexpected response")

        text = _extract_output_text(decoded)
        return Response(
            text=text,
            id=_optional_string(decoded.get("id")),
            model=_optional_string(decoded.get("model")),
            raw=decoded,
        )


def _optional_string(value: Any) -> str | None:
    return value if isinstance(value, str) else None


def _extract_output_text(response: Mapping[str, Any]) -> str:
    """Collect text parts without assuming every output item is a message."""
    top_level = response.get("output_text")
    if isinstance(top_level, str):
        return top_level

    parts: list[str] = []
    output = response.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict) or item.get("type") != "message":
                continue
            content = item.get("content")
            if not isinstance(content, list):
                continue
            for part in content:
                if (
                    isinstance(part, dict)
                    and part.get("type") == "output_text"
                    and isinstance(part.get("text"), str)
                ):
                    parts.append(part["text"])
    if not parts:
        raise OpenAIError("OpenAI API response contained no text output")
    return "".join(parts)


def send_prompt(
    prompt: str,
    *,
    model: str = "gpt-5-mini",
    api_key: str | None = None,
    timeout: float = 60.0,
) -> str:
    """Convenience wrapper returning only the generated text."""
    return OpenAIClient(api_key=api_key, model=model, timeout=timeout).respond(prompt).text


__all__ = ["OpenAIClient", "OpenAIError", "Response", "send_prompt"]
